questionvariables.text:
p_val: rand([0.4, 0.5, 0.6]);
x1: rand([80, 100, 120]);
x2: rand([10, 20, 30]);

ta1: float(p_val*x1 + (1-p_val)*x2);
EV: ta1;

ta2: float(p_val*sqrt(x1) + (1-p_val)*sqrt(x2));
U_EV: float(sqrt(EV));

ta3: [[1, true, "Risk-averse"], [2, false, "Risk-neutral"], [3, false, "Risk-loving"]];

ta4: float(ta2^2);
ta5: float(EV - ta4);
